class Solution:
    def countBlocks(self, reader) -> int:
        n = reader.length()
        ans, i = 0, 0
        while i < n:
            ans += 1
            v = reader.at(i)
            lo, hi, nxt = i + 1, n - 1, n
            while lo <= hi:
                mid = (lo + hi) // 2
                if reader.at(mid) == v:
                    lo = mid + 1
                else:
                    nxt = mid
                    hi = mid - 1
            i = nxt
        return ans

