 *  public:
 *   int at(long long index);
 *   long long length();
 * };
 */
class Solution {
public:
    int countBlocks(ArrayReader &reader) {
        long long n = reader.length();
        int ans = 0;
        long long i = 0;
        while (i < n) {
            ans++;
            int v = reader.at(i);
            long long lo = i + 1, hi = n - 1, nxt = n;
            while (lo <= hi) {
                long long mid = (lo + hi) / 2;
                if (reader.at(mid) == v) lo = mid + 1;
                else { nxt = mid; hi = mid - 1; }
            }
            i = nxt;
        }
        return ans;
    }
};

