/**
 * // This is ArrayReader's API interface.
 * var ArrayReader = function() { this.at = function(index) {}; this.length = function() {}; };
 */
var countBlocks = function(reader) {
    const n = reader.length();
    let ans = 0, i = 0;
    while (i < n) {
        ans++;
        const v = reader.at(i);
        let lo = i + 1, hi = n - 1, nxt = n;
        while (lo <= hi) {
            const mid = Math.floor((lo + hi) / 2);
            if (reader.at(mid) === v) lo = mid + 1;
            else { nxt = mid; hi = mid - 1; }
        }
        i = nxt;
    }
    return ans;
};
